<?php require 'bootstrap.php';require_login();require 'layout.php';$s=db()->prepare('SELECT o.*,p.method,p.status payment_status FROM orders o LEFT JOIN payments p ON p.order_id=o.id WHERE o.user_id=? ORDER BY o.id DESC');$s->execute([current_user()['id']]);head_html('Orders');?><h1>My orders</h1><?php if(isset($_GET['placed'])):?><p class="alert success">Order placed successfully! #<?= (int)$_GET['placed']?></p><?php endif;?><div class="panel"><table class="table"><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th>Payment</th></tr><?php foreach($s as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['created_at'])?></td><td>₱<?=number_format($o['total'],2)?></td><td><?=e($o['status'])?></td><td><?=e($o['payment_status'])?></td></tr><?php endforeach;?></table></div><?php foot_html();